    if (whz2RockAtkPerRound() != 4
            || whz2RockDurationMin() + 3 != whz2RockDurationMax()
        )
            ++bad;
        // the two cliff-face count formulas agree in range - 1d4-1 for the
        // warned climbers and 1d6-3 for the unwarned, both topping out at 3
