        // code is T W Z - the T low almost never below 70, the Z high up to
        // 115, the W mean high 95 low 75
    if (wwsA1LoM07(22) != 19
            || wwsA1MeanM07(22) != 22
            || wwsA1HiM07(22) != 25
        )
            ++bad;
