        // is A E J, and a roll of 12 from the E mean stops at the J upper
        // limit, never K
    if (wwsA1LoM01(7) != 0
            || wwsA1MeanM01(7) != 4
            || wwsA1HiM01(7) != 9
        )
            ++bad;
