    if (dnxT18Loc(2) != 2
            || dnxT18Above(2) != 5
            || dnxT18Next(2) != 12
            || dnxT18Loc(3) != 3
            || dnxT18Above(3) != 80
            || dnxT18Next(3) != 4
        )
            ++bad;
        printf("R512 DSG chain reaction audit: bad %d\n", bad);
        if (bad) return 1;
